panda_query_payload.query_template:
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX : <https://rsp.js/>
REGISTER RStream <output_{benchmark_run_id}> AS
SELECT (AVG(?o) AS ?avgHeartRateFromIbi)
FROM NAMED WINDOW :w1 ON STREAM <http://localhost:3000/alice/derived/spo2-last-10-min/> [RANGE 600000 STEP 600000]
WHERE {
  WINDOW :w1 {
    ?s saref:hasValue ?o .
  }
}

panda_query_payload.rules:
@prefix saref: <https://saref.etsi.org/core/> .
@prefix math: <http://www.w3.org/2000/10/swap/math#> .
@prefix ex: <http://example.org/> .

{ ?s saref:hasValue ?heartRateValue . ?heartRateValue math:lessThan 90. } => { ?s ex:alert "HEART_RATE_ALERT" } .
